cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));

// Find user by email
const users = db.prepare(\"SELECT * FROM users WHERE email = ?\").all('maya.chen@email.com');
if (users.length === 0) {
  // Try searching across all tables
  tables.forEach(t => {
    const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
    console.log(t.name + ':', cols.map(c => c.name));
  });
} else {
  console.log('User:', JSON.stringify(users, null, 2));
}
"

