cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Check which user has the tau2Retail skill and look for order ORD-D7E869
// Also check orders table for that order
const order = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%D7E869%'\").all();
